source("pre.R")
P <- function(label, expr) { cat("---", label, ": "); r <- try_(expr); if (!is.null(r)) { if (is.character(r)) cat(r, sep = "\n") else try_(print(r)) }; invisible(r) }
kw <- jwk_generate("oct", alg = "A128KW", kid = "kek")
kw256 <- jwk_generate("oct", alg = "A256KW", kid = "kek2")
gk <- jwk_generate("oct", alg = "A256GCMKW", kid = "g")
pw <- jwk_oct(charToRaw("password"))
rsa <- jwk_generate("RSA", kid = "r"); ec <- jwk_generate("EC", kid = "e"); okp <- jwk_generate("OKP", kid = "x")
encs <- c("A128CBC-HS256","A192CBC-HS384","A256CBC-HS512","A128GCM","A192GCM","A256GCM")
cat("=== roundtrip matrix (plaintext x alg x enc x format)\n")
cases <- list(list(kw, "A128KW"), list(gk, "A256GCMKW"), list(pw, "PBES2-HS384+A192KW"), list(rsa, "RSA-OAEP-256"), list(rsa, "RSA-OAEP"), list(ec, "ECDH-ES"), list(ec, "ECDH-ES+A192KW"), list(okp, "ECDH-ES"), list(okp, "ECDH-ES+A256KW"))
bad <- 0
for (cs in cases) for (enc in encs) for (f in c("compact","flattened","general")) for (p in list("", "x", "café\n", as.raw(0:255))) {
  hdr <- if (grepl("PBES2", cs[[2]])) list(p2c = 1000) else NULL
  aad <- if (f != "compact") "aadé" else NULL
  t <- tryCatch(jwe_encrypt(p, cs[[1]], cs[[2]], enc, header = hdr, format = f, aad = aad, unprotected = if (f != "compact") list(u = 1)), error = function(e) e)
  if (inherits(t, "error")) { bad <- bad + 1; cat("ENC ERR", cs[[2]], enc, f, conditionMessage(t), "\n"); next }
  d <- tryCatch(jwe_decrypt(t, cs[[1]], cs[[2]], enc), error = function(e) e)
  want <- if (is.raw(p)) p else charToRaw(enc2utf8(p))
  if (inherits(d, "error")) { bad <- bad + 1; cat("DEC ERR", cs[[2]], enc, f, deparse(p)[1], conditionMessage(d), "\n") }
  else if (!identical(d$plaintext, want) || d$alg != cs[[2]] || d$enc != enc || !identical(d$kid, cs[[1]]$kid)) { bad <- bad + 1; cat("MISMATCH", cs[[2]], enc, f, "\n") }
}
cat("bad:", bad, "\n")
cat("=== dir\n")
for (enc in encs) { n <- c(32, 48, 64, 16, 24, 32)[match(enc, encs)]; k <- jwk_oct(as.raw(seq_len(n)), kid = "d"); for (f in c("compact","flattened","general")) { t <- try_(jwe_encrypt("x", k, "dir", enc, format = f)); d <- try_(jwe_decrypt(t, k, "dir", enc)); if (!identical(d$plaintext, charToRaw("x"))) cat("dir fail", enc, f, "\n") } }
P("dir general token", jwe_encrypt("x", jwk_oct(as.raw(1:32), kid = "d"), "dir", format = "general"))
P("dir flattened token", jwe_encrypt("x", jwk_oct(as.raw(1:32), kid = "d"), "dir", format = "flattened"))
P("dir key alg=enc", { k <- jwk_oct(as.raw(1:16), alg = "A128GCM"); t <- jwe_encrypt("x", k, "dir", "A128GCM"); rawToChar(jwe_decrypt(t, k, "dir", "A128GCM")$plaintext) })
P("dir key alg=enc, alg NULL", { k <- jwk_oct(as.raw(1:16), alg = "A128GCM"); jwe_encrypt("x", k, enc = "A128GCM") })
cat("=== header shapes\n")
P("compact kw", header_of(jwe_encrypt("x", kw)))
P("general kw", jwe_encrypt("x", kw, format = "general", header = list(typ = "JWT"), unprotected = list(u = "v"), aad = "a"))
P("flattened pbes2", jwe_encrypt("x", pw, "PBES2-HS256+A128KW", format = "flattened", header = list(p2c = 1000)))
P("general pbes2 p2c in protected", { t <- jwe_encrypt("x", pw, "PBES2-HS256+A128KW", format = "general", header = list(p2c = 1000)); cat(t, "\n"); cat(dec(zujson::json_parse(t, simplify="none")$protected), "\n"); rawToChar(jwe_decrypt(t, pw, "PBES2-HS256+A128KW", "A128CBC-HS256")$plaintext) })
P("general pbes2 p2c in unprotected", { t <- jwe_encrypt("x", pw, "PBES2-HS256+A128KW", format = "general", unprotected = list(p2c = 1000)); cat(t, "\n"); rawToChar(jwe_decrypt(t, pw, "PBES2-HS256+A128KW", "A128CBC-HS256")$plaintext) })
P("recipient-level p2c", { t <- jwe_encrypt("x", list(jwe_recipient(pw, "PBES2-HS256+A128KW", header = list(p2c = 2000))), format = "general"); cat(t, "\n"); rawToChar(jwe_decrypt(t, pw, "PBES2-HS256+A128KW", "A128CBC-HS256")$plaintext) })
for (p in list(1000, 1000L, 999, 1000.5, "1000", NA, 1e5, 4294967296, c(1000, 2000), TRUE, -1, Inf)) P(paste("p2c", deparse(p)), { t <- jwe_encrypt("x", pw, "PBES2-HS256+A128KW", header = list(p2c = p)); header_of(t) })
P("p2c on non-pbes2", jwe_encrypt("x", kw, header = list(p2c = 1000)))
P("partial: header p2 on non-pbes2", header_of(jwe_encrypt("x", kw, header = list(p2 = 1000))))
P("partial: header p2 on pbes2", header_of(jwe_encrypt("x", pw, "PBES2-HS256+A128KW", header = list(p2 = 1000))))
P("header alg", jwe_encrypt("x", kw, header = list(alg = "A128KW")))
P("header enc", jwe_encrypt("x", kw, header = list(enc = "A128GCM")))
P("header zip", jwe_encrypt("x", kw, header = list(zip = "DEF")))
P("unprotected zip", jwe_encrypt("x", kw, format = "flattened", unprotected = list(zip = "DEF")))
P("unprotected alg", jwe_encrypt("x", kw, format = "flattened", unprotected = list(alg = "dir")))
P("unprotected enc", jwe_encrypt("x", kw, format = "flattened", unprotected = list(enc = "A256GCM")))
P("header iv", jwe_encrypt("x", gk, header = list(iv = "AAAA")))
P("header iv with A128KW", jwe_encrypt("x", kw, header = list(iv = "AAAA")))
P("header kid override", header_of(jwe_encrypt("x", kw, header = list(kid = "other"))))
P("header dup", header_of(jwe_encrypt("x", kw, header = list(a = 1, a = 2))))
P("header crit", jwe_encrypt("x", kw, header = list(crit = list("x"), x = 1)))
P("header b64", jwe_encrypt("x", kw, header = list(b64 = FALSE)))
P("header cty num", jwe_encrypt("x", kw, header = list(cty = 5)))
P("compact with aad", jwe_encrypt("x", kw, aad = "a"))
P("compact with unprotected", jwe_encrypt("x", kw, unprotected = list(a = 1)))
P("aad empty string flattened", { t <- jwe_encrypt("x", kw, aad = "", format = "flattened"); cat(t, "\n"); rawToChar(jwe_decrypt(t, kw, "A128KW", "A128CBC-HS256")$plaintext) })
P("aad raw 0", { t <- jwe_encrypt("x", kw, aad = raw(), format = "flattened"); rawToChar(jwe_decrypt(t, kw, "A128KW", "A128CBC-HS256")$plaintext) })
P("aad number", jwe_encrypt("x", kw, aad = 5, format = "flattened"))
for (e in list("a128gcm", NA_character_, c("A128GCM","A256GCM"), NULL, "A128KW", factor("A128GCM"))) P(paste("enc", deparse(e)), jwe_encrypt("x", kw, enc = e))
for (a in list("RSA1_5", "none", "HS256", NA_character_, c("A128KW","A256KW"), "A256KW", "dir")) P(paste("alg", deparse(a)), jwe_encrypt("x", jwk_oct(as.raw(1:16)), alg = a))
P("apu/apv", { t <- jwe_encrypt("x", ec, "ECDH-ES", header = list(apu = "QWxpY2U", apv = "Qm9i")); cat(header_of(t), "\n"); rawToChar(jwe_decrypt(t, ec, "ECDH-ES", "A128CBC-HS256")$plaintext) })
P("apu non-b64", jwe_encrypt("x", ec, "ECDH-ES", header = list(apu = "Alice!")))
P("apu number", jwe_encrypt("x", ec, "ECDH-ES", header = list(apu = 5)))
P("apu raw", jwe_encrypt("x", ec, "ECDH-ES", header = list(apu = charToRaw("Alice"))))
P("apu on A128KW", header_of(jwe_encrypt("x", kw, header = list(apu = "QWxpY2U"))))
P("epk given", jwe_encrypt("x", ec, "ECDH-ES", header = list(epk = list(kty = "EC"))))
P("ecdh epk has no d", { h <- zujson::json_parse(header_of(jwe_encrypt("x", ec, "ECDH-ES")), simplify = "none"); names(h$epk) })
P("ecdh public only key encrypt", { t <- jwe_encrypt("x", jwk_public(ec), "ECDH-ES+A128KW"); rawToChar(jwe_decrypt(t, ec, "ECDH-ES+A128KW", "A128CBC-HS256")$plaintext) })
P("ecdh decrypt with public", { t <- jwe_encrypt("x", jwk_public(ec), "ECDH-ES+A128KW"); jwe_decrypt(t, jwk_public(ec), "ECDH-ES+A128KW", "A128CBC-HS256") })
P("rsa decrypt with public", { t <- jwe_encrypt("x", jwk_public(rsa), "RSA-OAEP"); jwe_decrypt(t, jwk_public(rsa), "RSA-OAEP", "A128CBC-HS256") })
cat("=== multi recipients\n")
t <- P("multi", jwe_encrypt("hello", list(jwe_recipient(kw, "A128KW"), jwe_recipient(rsa, "RSA-OAEP-256", header = list(note = "x")), jwe_recipient(pw, "PBES2-HS256+A128KW", header = list(p2c = 1000)), jwe_recipient(ec, "ECDH-ES+A128KW"), jwe_recipient(gk)), format = "general"))
for (cs in list(list(kw, "A128KW"), list(rsa, "RSA-OAEP-256"), list(pw, "PBES2-HS256+A128KW"), list(ec, "ECDH-ES+A128KW"), list(gk, "A256GCMKW"))) { d <- try_(jwe_decrypt(t, cs[[1]], cs[[2]], "A128CBC-HS256")); cat(cs[[2]], rawToChar(d$plaintext), d$alg, d$kid, paste(names(d$header), collapse = ","), "\n") }
P("multi named list", jwe_encrypt("hello", list(a = jwe_recipient(kw, "A128KW"), b = jwe_recipient(kw256)), format = "general"))
P("multi compact", jwe_encrypt("hello", list(jwe_recipient(kw, "A128KW"), jwe_recipient(kw256))))
P("single recipient compact with header", jwe_encrypt("hello", list(jwe_recipient(kw, "A128KW", header = list(a = 1)))))
P("single recipient flattened with header", jwe_encrypt("hello", list(jwe_recipient(kw, "A128KW", header = list(a = 1))), format = "flattened"))
P("recipient alg + alg arg", jwe_encrypt("hello", list(jwe_recipient(kw)), alg = "A128KW"))
P("multi with dir", jwe_encrypt("hello", list(jwe_recipient(jwk_oct(as.raw(1:32)), "dir"), jwe_recipient(kw)), format = "general"))
P("recipient header alg", jwe_encrypt("hello", list(jwe_recipient(kw, header = list(alg = "A256KW")), jwe_recipient(kw256)), format = "general"))
P("recipient header enc", jwe_encrypt("hello", list(jwe_recipient(kw, header = list(enc = "A256GCM")), jwe_recipient(kw256)), format = "general"))
P("recipient header zip", jwe_encrypt("hello", list(jwe_recipient(kw, header = list(zip = "DEF")), jwe_recipient(kw256)), format = "general"))
P("same kid twice", { t <- jwe_encrypt("hello", list(jwe_recipient(kw), jwe_recipient(kw)), format = "general"); rawToChar(jwe_decrypt(t, kw, "A128KW", "A128CBC-HS256")$plaintext) })
cat("=== decrypt args\n")
t1 <- jwe_encrypt("x", kw)
for (a in list(NULL, "none", "HS256", c("A128KW","dir"), "dir", factor("A128KW"))) P(paste("algorithms", deparse(a)), class(jwe_decrypt(t1, kw, a, "A128CBC-HS256")))
for (e in list(NULL, "A128KW", c("A128GCM","A128CBC-HS256"), "A128GCM")) P(paste("encryptions", deparse(e)), class(jwe_decrypt(t1, kw, "A128KW", e)))
P("decrypt JWS", jwe_decrypt(jws_sign("x", key, "HS256"), kw, "A128KW", "A128CBC-HS256"))
P("verify JWE", jws_verify(t1, key, "HS256"))
P("decrypt with set", jwe_decrypt(t1, jwk_set(kw256, kw, rsa), "A128KW", "A128CBC-HS256")$kid)
P("decrypt with resolver", jwe_decrypt(t1, function(h) { cat("[", names(h), "]"); kw }, "A128KW", "A128CBC-HS256")$kid)
P("decrypt with resolver returning NULL", jwe_decrypt(t1, function(h) NULL, "A128KW", "A128CBC-HS256"))
P("decrypt wrong key", jwe_decrypt(t1, jwk_oct(as.raw(1:16)), "A128KW", "A128CBC-HS256"))
P("decrypt wrong size key", jwe_decrypt(t1, kw256, "A128KW", "A128CBC-HS256"))
P("print decrypted", jwe_decrypt(t1, kw, "A128KW", "A128CBC-HS256"))
P("jwe_decryption print", jwe_decryption(kw, "A128KW", "A128CBC-HS256"))
P("jwe_decryption bad key", jwe_decryption("x", "A128KW", "A128CBC-HS256"))
P("jwe_decryption raw key", jwe_decryption(as.raw(1:16), "A128KW", "A128CBC-HS256"))
P("peek jwe", jose_peek(jwe_encrypt("x", kw, format = "general", aad = "a")))
